// Endpoint resolution (Phase 4 Scenario B baas.<custom-domain> first-party cookie).
// Logic mirrors src/lib/baas-endpoint-resolver.ts in paletto-server — keep in sync.
//   1. import.meta.env.VITE_APPWRITE_ENDPOINT override (testing, custom routing).
//   2. SSR / no `window` → throw (no silent fallback — would split cookie jars).
//   3. localhost / preview hosts → use provisioned backendhub endpoint (dev).
//   4. Otherwise: strip leading "www." then https://baas.<host>/v1 (first-party).
//
// If the customer has not added the baas.<X> CNAME yet, network calls to
// baas.<X> will fail (DNS or TLS). The customer's app falls back gracefully
// only if they catch and retry against https://backendhub.paletto.sh/v1; otherwise the
// recommended UX is to surface a setup banner. See docs/operations/custom-domain.md.
const endpoint: string = (() => {
  // @ts-ignore — Vite injects this at build; absent in SSR / Node test runners.
  const override = typeof import.meta !== "undefined" && import.meta.env
    ? import.meta.env.VITE_APPWRITE_ENDPOINT
    : undefined;
  if (override) return override;

  if (typeof window === "undefined") {
    throw new Error(
      "[paletto-baas] Helper requires a browser context. Set VITE_APPWRITE_ENDPOINT to use this helper during SSR / build.",
    );
  }

  const raw = window.location.hostname.toLowerCase();
  const host = raw.startsWith("www.") ? raw.slice(4) : raw;

  if (
    host === "localhost" ||
    host === "127.0.0.1" ||
    // Local dev preview serves each project on a `<folder>.localhost` subdomain.
    // `.localhost` is reserved loopback (RFC 6761) so this never matches real
    // production traffic — safe to route to the provisioned endpoint.
    host.endsWith(".localhost") ||
    // One family per environment (prod / staging / beta). A missing family does NOT fail
    // safe: it falls through to `https://baas.<host>/v1` and invents a hostname nobody
    // provisioned. Keep in sync with baas-endpoint-resolver.ts.
    host.endsWith(".preview.paletto.sh") ||
    host.endsWith(".preview.staging.paletto.sh") ||
    host.endsWith(".preview.studio.paletto.sh") ||
    host.endsWith(".template.paletto.sh") ||
    host.endsWith(".template.staging.paletto.sh") ||
    host.endsWith(".template.studio.paletto.sh") ||
    host === "preview.paletto.sh" ||
    host === "preview.staging.paletto.sh" ||
    host === "preview.studio.paletto.sh"
  ) {
    return "https://backendhub.paletto.sh/v1";
  }

  return `https://baas.${host}/v1`;
})();

