let currentUid: string | null = null;

let authModeExplicit = false;
/**
 * Toggle whether {@link getUid} may bootstrap an anonymous session.
 *
 * - `"anonymous"` (default): legacy anon-first. `getUid()` creates an anon
 *   session when none exists. Right for guest-friendly apps (notes, todos,
 *   shop browsing). Anon can later upgrade via {@link signInWithOAuth} or via
 *   {@link updateEmail} + {@link updatePassword} without losing docs.
 * - `"explicit"`: `getUid()` THROWS when no session exists. Right for apps
 *   with a sign-up / login screen — prevents the silent anon session that
 *   would orphan data once the user runs {@link signUpWithEmail}
 *   (Appwrite's `createEmailPasswordSession` does NOT merge an existing
 *   anon session).
 *
 * Call ONCE at the top of `main.tsx`, before any `db.*` / `storage.*` /
 * `subscribe*` call — including effects that fire during initial render.
 * See `patterns/explicit-auth-gate.md` for the full sign-up/login flow.
 *
 * @example
 * // main.tsx — explicit-auth app
 * import { setAuthMode } from './lib/baas';
 * setAuthMode('explicit');
 */
export function setAuthMode(mode: "anonymous" | "explicit"): void {
  authModeExplicit = mode === "explicit";
}

// Appwrite anonymous users have empty email + empty name. Real users (email/
// password sign-up, OAuth) always have an email — providers fill it from the
// social profile, signUpWithEmail requires it. Reliable check for "is this
// session anonymous?" without an extra account.getSession() round-trip.
function isAnonymousUser(user: Models.User<Models.Preferences>): boolean {
  return user.email === "" && user.name === "";
}

/**
 * Bootstrap or reuse a session — single source of truth for visitor identity.
 * Returns the userId Appwrite assigns; cached for the lifetime of the page.
 *
 * In `"explicit"` mode, throws when no session exists OR when the existing
 * session is anonymous. Anonymous sessions are KILLED on detection — they
 * must not survive in an explicit-auth app (otherwise a stale visitor cookie
 * lets the unauthed visitor read/write data after the app added login).
 *
 * @example
 * const uid = await getUid();
 */
export async function getUid(): Promise<string> {
  if (currentUid) return currentUid;
  try {
    const me = await account.get();
    if (authModeExplicit && isAnonymousUser(me)) {
      // Stale anon cookie in an explicit-mode app. Kill it so getCurrentUser
      // returns null on the next call and the UI re-renders to the login gate.
      await account.deleteSession("current").catch(() => { /* already gone */ });
      throw new Error(
        "[baas] Stale anonymous session detected in explicit auth mode. The session has been cleared — call signUpWithEmail / signInWithEmail / signInWithOAuth to authenticate.",
      );
    }
    currentUid = me.$id;
  } catch (err) {
    if (currentUid) return currentUid; // race-safe: another caller succeeded
    if (err instanceof Error && err.message.startsWith("[baas]")) throw err;
    if (authModeExplicit) {
      throw new Error(
        "[baas] Not signed in. The app is in explicit auth mode — call signUpWithEmail / signInWithEmail / signInWithOAuth before any db.*/storage.*/subscribe* operation.",
      );
    }
    const sess = await account.createAnonymousSession();
    currentUid = sess.userId;
  }
  return currentUid;
}

/**
 * Non-side-effect identity check. Returns the current Appwrite user OR `null`
 * if no real session exists. NEVER bootstraps an anonymous session — safe to
 * call from route guards / auth contexts to decide whether to render the
 * login UI.
 *
 * In `"explicit"` mode, returns `null` for anonymous sessions AND kills them.
 * This handles the upgrade case: an app that started anonymous (visitor got
 * an anon cookie on first visit) then later added login — without this
 * filter, the stale anon session would lift the auth gate and the visitor
 * would access the app without ever signing in.
 *
 * @example
 * const user = await getCurrentUser();
 * if (!user) {
 *   // render <SignIn /> ; no db.* / storage.* allowed here
 * } else {
 *   // render <App user={user} />
 * }
 */
export async function getCurrentUser(): Promise<Models.User<Models.Preferences> | null> {
  try {
    const me = await account.get();
    if (authModeExplicit && isAnonymousUser(me)) {
      await account.deleteSession("current").catch(() => { /* already gone */ });
      currentUid = null;
      return null;
    }
    return me;
  } catch {
    return null;
  }
}

// --- Demo isolation (per-browser tenant) ----------------------------------------------------
// A template can double as a real app AND a public showcase demo served on a shared backend. In a
// DEMO, every visitor hits the same backend, so without isolation one visitor's data (and even a
// changed demo account's name) leaks to the next. When a demo persona activates a tenant (via
// setDemoTenant), we tag every created document with a per-browser `demoTenant` and filter every
// list by it — each browser gets its own private data. REAL signed-up users NEVER set a tenant,
// so their queries are unfiltered and the app behaves exactly as before. Inert unless a demo opts
// in, so it is safe to ship in every generated app. Requires a `demoTenant` string attribute +
// index on each collection used in demo mode (see the app's .paletto/schema.json).
const DEMO_TENANT_KEY = "demoTenant";
export const DEMO_TENANT_FIELD = "demoTenant";
// In-memory fallback if localStorage is unavailable (private mode / blocked) — keeps the tenant
// stable for the tab so a demo session is never silently un-isolated.
let demoTenantMemory: string | null = null;

export function getDemoTenant(): string | null {
  if (demoTenantMemory) return demoTenantMemory;
  try {
    const v = localStorage.getItem(DEMO_TENANT_KEY);
    if (v) demoTenantMemory = v;
    return v;
  } catch {
    return demoTenantMemory;
  }
}
export function setDemoTenant(tenant: string): void {
  demoTenantMemory = tenant;
  try { localStorage.setItem(DEMO_TENANT_KEY, tenant); } catch { /* private mode — memory fallback */ }
}
export function clearDemoTenant(): void {
  demoTenantMemory = null;
  try { localStorage.removeItem(DEMO_TENANT_KEY); } catch { /* ignore */ }
}

export type Scope = "user" | "shared" | "authenticated" | "public" | "app-owner";

export interface PermsOpts {
  scope?: Scope;
  /** @deprecated retained for backward compat with code using scope="team" */
  teamId?: string;
}

// Returns the SDK permission strings for a given scope. Resolves the current
// user id at call time — Paletto's Appwrite fork does NOT support the
// `$userId` template var, so we substitute explicitly.
//
// Why no Role.team(X) per-doc perms: Appwrite restricts client-side perm grants
// to roles the caller already has (any, users, user:<own-uid>, users/unverified).
// Anonymous users belong to no team, so Role.team(X) fails with 401. Use
// Role.users() for shared semantics; route admin writes through curl + .paletto/baas.env.
async function permsFor(scope: Scope | "team"): Promise<string[]> {
  const uid = await getUid();
  switch (scope) {
    case "user":
      return [
        Permission.read(Role.user(uid)),
        Permission.update(Role.user(uid)),
        Permission.delete(Role.user(uid)),
      ];
    case "shared":
      return [
        Permission.read(Role.users()),
        Permission.update(Role.users()),
        Permission.delete(Role.users()),
      ];
    case "team":
      console.warn("[baas] scope 'team' is deprecated, use 'shared' instead");
      return [
        Permission.read(Role.users()),
        Permission.update(Role.users()),
        Permission.delete(Role.users()),
      ];
    case "authenticated":
      return [
        Permission.read(Role.users()),
        Permission.update(Role.user(uid)),
        Permission.delete(Role.user(uid)),
      ];
    case "public":
      return [
        Permission.read(Role.any()),
        Permission.update(Role.user(uid)),
        Permission.delete(Role.user(uid)),
      ];
    case "app-owner":
      throw new Error(
        "[baas] scope 'app-owner' is read-only from the client. Use db.list() / db.get() to read. Admin writes must use curl with .paletto/baas.env — see SKILL.md.",
      );
  }
}

// Document API. `scope` defaults to "user" (private, only creator can read/edit).
// Other scopes:
//   - "shared"        — RW among all app users (anyone with a session)
//   - "authenticated" — login-only read, creator writes
//   - "public"        — anyone reads, creator writes
//   - "app-owner"     — read-only from client; writes via curl + .paletto/baas.env
// See SKILL.md for picking the right scope.
//
// Generic <T> = your domain shape; the helper merges Models.Document fields
// ($id, $createdAt, $permissions, …) automatically. Do NOT make your interface
// extend Models.Document — pass the plain domain shape and the return type
// will be `T & Models.Document`. Example:
//   interface Note { title: string; body: string }
//   const n = await db.create<Note>("notes", { title, body });
//   n.$id; n.title;   // both work, no cast needed
export const db = {
  async create<T = Record<string, any>>(
    collection: string,
    data: Record<string, any>,
    opts: PermsOpts = {},
  ): Promise<T & Models.Document> {
    const perms = await permsFor(opts.scope ?? "user");
    // Demo isolation: tag the doc with the active per-browser tenant (no-op for real users).
    const tenant = getDemoTenant();
    const payload = tenant ? { ...data, [DEMO_TENANT_FIELD]: tenant } : data;
    return databases.createDocument(
      DB_ID,
      collection,
      ID.unique(),
      payload,
      perms,
    ) as unknown as T & Models.Document;
  },
  async list<T = Record<string, any>>(
    collection: string,
    queries: string[] = [],
  ): Promise<Models.DocumentList<T & Models.Document>> {
    await getUid();
    // Demo isolation: constrain every list to the active tenant so one browser never sees
    // another's demo data. Real users have no tenant → unfiltered, original behavior.
    const tenant = getDemoTenant();
    const scoped = tenant ? [Query.equal(DEMO_TENANT_FIELD, tenant), ...queries] : queries;
    return databases.listDocuments(DB_ID, collection, scoped) as unknown as Models.DocumentList<
      T & Models.Document
    >;
  },
  async get<T = Record<string, any>>(
    collection: string,
    id: string,
  ): Promise<T & Models.Document> {
    await getUid();
    return databases.getDocument(DB_ID, collection, id) as unknown as T & Models.Document;
  },
  async update<T = Record<string, any>>(
    collection: string,
    id: string,
    data: Record<string, any>,
  ): Promise<T & Models.Document> {
    await getUid();
    return databases.updateDocument(
      DB_ID,
      collection,
      id,
      data,
    ) as unknown as T & Models.Document;
  },
  async delete(collection: string, id: string): Promise<void> {
    await getUid();
    await databases.deleteDocument(DB_ID, collection, id);
  },
};

// Storage. `upload` auto-sets per-visitor read/update/delete perms (scope=user
// default), mirroring db.create. Bucket-level perms must be `create("users")`
// + `fileSecurity: true` — set out-of-band via curl + .paletto/baas.env.
export const storage = {
  async upload(
    bucketId: string,
    file: File,
    opts: PermsOpts = {},
  ): Promise<Models.File> {
    const perms = await permsFor(opts.scope ?? "user");
    return storage_internal.createFile(bucketId, ID.unique(), file, perms);
  },
  getView(bucketId: string, fileId: string): string {
    return storage_internal.getFileView(bucketId, fileId).toString();
  },
  getDownload(bucketId: string, fileId: string): string {
    return storage_internal.getFileDownload(bucketId, fileId).toString();
  },
  async list(bucketId: string, queries: string[] = []): Promise<Models.FileList> {
    await getUid();
    return storage_internal.listFiles(bucketId, queries);
  },
  async delete(bucketId: string, fileId: string): Promise<void> {
    await getUid();
    await storage_internal.deleteFile(bucketId, fileId);
  },
};

// Functions — client-side execute of a deployed Appwrite Function. Generic <T>
// hints the JSON shape consumer expects from `responseBody`; Appwrite returns
// it as a string so consumer is responsible for parsing.
export const functions = {
  async execute<T = unknown>(
    functionId: string,
    body?: string | Record<string, unknown>,
    async: boolean = false,
    path?: string,
    method?: "GET" | "POST" | "PUT" | "DELETE" | "PATCH" | "OPTIONS",
    headers?: Record<string, string>,
  ): Promise<Models.Execution & { responseBody: T }> {
    await getUid();
    const payload =
      body === undefined || typeof body === "string" ? body : JSON.stringify(body);
    // `method` cast: Appwrite SDK uses ExecutionMethod enum but accepts the
    // literal string at runtime. Keeping the string-union for ergonomics.
    const exec = await functions_internal.createExecution(
      functionId,
      payload,
      async,
      path,
      method as unknown as Parameters<typeof functions_internal.createExecution>[4],
      headers,
    );
    return exec as unknown as Models.Execution & { responseBody: T };
  },
};

// Realtime — Appwrite filters events server-side based on document permissions,
// so visitors only receive events for docs they can read.
export function subscribe<T = Models.Document>(
  collection: string,
  onEvent: (evt: RealtimeResponseEvent<T>) => void,
): () => void {
  return client.subscribe<T>(
    `databases.${DB_ID}.collections.${collection}.documents`,
    onEvent,
  );
}

// Realtime — account events (login, logout, profile update). Payload is the
// updated `Models.User<Models.Preferences>`.
export function subscribeAccount<T = Models.User<Models.Preferences>>(
  onEvent: (evt: RealtimeResponseEvent<T>) => void,
): () => void {
  return client.subscribe<T>("account", onEvent);
}

// Realtime — file events within a bucket. Server-side perm filter applies.
export function subscribeFiles<T = Models.File>(
  bucketId: string,
  onEvent: (evt: RealtimeResponseEvent<T>) => void,
): () => void {
  return client.subscribe<T>(`buckets.${bucketId}.files`, onEvent);
}

// Auth — anonymous by default. If the app needs a persistent account, call
// signInWithOAuth() (Google/Apple/GitHub) which UPGRADES the anonymous session
// to a real account, preserving all docs created so far.
//
// Uses oauthClient (pointed at provisioned backendhub.paletto.sh) regardless of
// custom-domain routing. OAuth providers' redirect_uri is registered against
// the backendhub callback path; pointing OAuth at baas.<custom-domain> would
// trigger redirect_uri_mismatch from Google/Apple/GitHub and fail silently.
export function signInWithOAuth(
  provider: OAuthProvider,
  redirectSuccess?: string,
  redirectFailure?: string,
): void {
  // Redirect-flow API. For the token-flow alternative use
  // `account.createOAuth2Token(...)` directly.
  oauthAccount.createOAuth2Session(provider, redirectSuccess, redirectFailure);
}

/**
 * Email / password sign-up. Creates the user, then opens the session so the
 * app is immediately authed. Throws on duplicate email or weak password —
 * surface the message in the form UI. Returns the freshly authed user so the
 * caller can re-render without a separate {@link getCurrentUser} call.
 *
 * REPLACES any prior session — including anonymous. Docs created under the
 * old anon uid become orphaned. For anon → email/password upgrade WITHOUT
 * data loss, use {@link updateEmail} + {@link updatePassword} instead (they
 * convert the current anon session into an email/password account in place).
 *
 * @example
 * // Sign-up form submit handler
 * const me = await signUpWithEmail(email, password, name);
 * // session open; re-render the app via your auth state
 */
export async function signUpWithEmail(
  email: string,
  password: string,
  name?: string,
): Promise<Models.User<Models.Preferences>> {
  await account.create(ID.unique(), email, password, name);
  // Clear any stale/anonymous session first — Appwrite 1.8 returns 401
  // ("session is active") when a session already exists at create time.
  await account.deleteSession("current").catch(() => { /* no session */ });
  await account.createEmailPasswordSession(email, password);
  currentUid = null;
  const me = await account.get();
  currentUid = me.$id;
  return me;
}

/**
 * Email / password sign-in for an existing account. Replaces any current
 * session (including anonymous — same orphan caveat as {@link signUpWithEmail}).
 *
 * @example
 * // Sign-in form submit handler
 * await signInWithEmail(email, password);
 */
export async function signInWithEmail(
  email: string,
  password: string,
): Promise<Models.User<Models.Preferences>> {
  // Clear any stale/anonymous session first — Appwrite 1.8 returns 401
  // ("session is active") when a session already exists at create time.
  await account.deleteSession("current").catch(() => { /* no session */ });
  await account.createEmailPasswordSession(email, password);
  currentUid = null;
  const me = await account.get();
  currentUid = me.$id;
  return me;
}

export async function signOut(): Promise<void> {
  await account.deleteSession("current");
  currentUid = null;
}

// Account profile updates. Visitor must already have a session (anonymous or
// OAuth). `updateEmail` / `updatePassword` require an email/password account —
// pure OAuth visitors have neither and will get a 4xx until they convert.
export async function updateName(name: string): Promise<Models.User<Models.Preferences>> {
  return account.updateName(name);
}

export async function updateEmail(
  email: string,
  password: string,
): Promise<Models.User<Models.Preferences>> {
  return account.updateEmail(email, password);
}

export async function updatePassword(
  newPassword: string,
  oldPassword: string,
): Promise<Models.User<Models.Preferences>> {
  return account.updatePassword(newPassword, oldPassword);
}
